export function parseIso(s){
  const m = /^P(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$/.exec(s);
  if (!m) throw new Error(`bad duration ${s}`);
  const [, d = 0, h = 0, mi = 0, se = 0] = m.map(x => x ?? 0);
  return Number(d) * 86400 + Number(h) * 3600 + Number(mi) * 60 + Number(se);
}

